from datetime import datetime
import calendar

# --- Login tokens ---
phone_pw = venmo_pw = None
for rec in apis.supervisor.show_account_passwords():
    if rec['account_name']=='phone':
        phone_pw = rec['password']
    if rec['account_name']=='venmo':
        venmo_pw = rec['password']

phone_token = apis.phone.login(username='3643463570', password=phone_pw)['access_token']
venmo_token = apis.venmo.login(username='anita.burch@gmail.com', password=venmo_pw)['access_token']

now = datetime.now()
last_day = calendar.monthrange(now.year, now.month)[1]
month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
month_end = now.replace(day=last_day, hour=23, minute=59, second=59, microsecond=999999)
print('now', now.isoformat())
print('month_start', month_start.isoformat())
print('month_end', month_end.isoformat())

# --- Identity resolution: phone contacts FIRST ---
contact_query = 'Sabrina'
page_limit = 20
page_index = 0
all_contacts = []
while True:
    resp = apis.phone.search_contacts(access_token=phone_token, query=contact_query, page_index=page_index, page_limit=page_limit)
    # response could be list or dict
    if not resp:
        break
    if isinstance(resp, dict) and 'contacts' in resp:
        page_items = resp['contacts']
    else:
        page_items = resp
    if not page_items:
        break
    all_contacts.extend(page_items)
    print('contacts page', page_index, 'count', len(page_items))
    if len(page_items) < page_limit:
        break
    page_index += 1

print('Total contacts matching query', contact_query, ':', len(all_contacts))
print('Sample contacts:', [(c.get('first_name'), c.get('last_name'), c.get('email'), c.get('phone_number')) for c in all_contacts[:10]])

# Post-filter exact match on first_name == Sabrina (case-insensitive)
filtered_contacts = [c for c in all_contacts if (c.get('first_name','') or '').strip().lower() == 'sabrina']
print('After exact-match post-filter first_name==Sabrina:', len(filtered_contacts))
for c in filtered_contacts:
    print('CONTACT', c.get('contact_id'), c.get('first_name'), c.get('last_name'), 'email', c.get('email'))

# If none found, we cannot act (would be unsafe)
if not filtered_contacts:
    print('NO CONTACTS FOUND for Sabrina; target set would be empty.')

# --- Map contacts to Venmo users ---

def venmo_user_exact_match(users, contact):
    # contact: dict with email or first_name/last_name
    email = (contact.get('email') or '').strip().lower()
    if email and '@' in email:
        return [u for u in users if (u.get('email') or '').strip().lower() == email]
    fn = (contact.get('first_name') or '').strip().lower()
    ln = (contact.get('last_name') or '').strip().lower()
    if fn or ln:
        return [u for u in users if (u.get('first_name') or '').strip().lower() == fn and (u.get('last_name') or '').strip().lower() == ln]
    return []

resolved_users = []
for c in filtered_contacts:
    q = (c.get('email') or '').strip() if c.get('email') else f"{c.get('first_name','')} {c.get('last_name','')}".strip()
    # paginate venmo user search
    u_page_index = 0
    u_page_limit = 20
    collected = []
    while True:
        su = apis.venmo.search_users(access_token=venmo_token, query=q, page_index=u_page_index, page_limit=u_page_limit)
        if not su:
            break
        if isinstance(su, dict) and 'users' in su:
            page_users = su['users']
        else:
            page_users = su
        if not page_users:
            break
        collected.extend(page_users)
        if len(page_users) < u_page_limit:
            break
        u_page_index += 1
    exact = venmo_user_exact_match(collected, c)
    print('Mapped contact', c.get('contact_id'), 'query', q, 'collected', len(collected), 'exact', len(exact))
    for u in exact:
        print('  VU', u.get('first_name'), u.get('last_name'), 'email', u.get('email'))
    resolved_users.extend(exact)

# Deduplicate by email when available else by name
uniq = {}
for u in resolved_users:
    key = (u.get('email') or '').strip().lower() if u.get('email') else None
    if key:
        uniq[key] = u
    else:
        name_key = f"{(u.get('first_name') or '').strip().lower()}|{(u.get('last_name') or '').strip().lower()}"
        uniq[name_key] = u
resolved_users = list(uniq.values())

resolved_emails = set([ (u.get('email') or '').strip().lower() for u in resolved_users if (u.get('email') or '').strip() ])
resolved_names = set([ f"{(u.get('first_name') or '').strip()} {(u.get('last_name') or '').strip()}".strip().lower() for u in resolved_users if (u.get('first_name') or '').strip() or (u.get('last_name') or '').strip() ])

print('Total resolved venmo users:', len(resolved_users))
print('Resolved emails:', sorted(list(resolved_emails)))
print('Resolved names:', sorted(list(resolved_names)))

# --- Fetch pending payment requests (received) and filter by month and sender identity ---

def parse_dt(s):
    if not s:
        return None
    try:
        # Handle trailing Z
        ss = s.replace('Z','+00:00')
        return datetime.fromisoformat(ss)
    except Exception:
        return None

reqs = []
page_index = 0
while True:
    resp = apis.venmo.show_received_payment_requests(access_token=venmo_token, status='pending', page_index=page_index, page_limit=20)
    if not resp:
        break
    if isinstance(resp, dict) and 'payment_requests' in resp:
        page_items = resp['payment_requests']
    else:
        page_items = resp
    if not page_items:
        break
    reqs.extend(page_items)
    print('pending payment_requests page', page_index, 'count', len(page_items))
    if len(page_items) < 20:
        break
    page_index += 1

print('Total pending received payment requests:', len(reqs))

matching = []
for r in reqs:
    created = parse_dt(r.get('created_at'))
    if not created:
        continue
    if not (month_start <= created <= month_end):
        continue
    sender = r.get('sender') or {}
    sender_email = (sender.get('email') or '').strip().lower()
    sender_name = (sender.get('name') or '').strip().lower()
    id_match = False
    if sender_email and resolved_emails and sender_email in resolved_emails:
        id_match = True
    if (not id_match) and sender_name and resolved_names and sender_name in resolved_names:
        id_match = True
    if id_match:
